(() => {
  "use strict";
  Object.defineProperty(window, "RMLHelpTemplateMarkup", {
    value: "    <dialog\n      id=\"information-dialog\"\n      class=\"information-dialog\"\n      tabindex=\"-1\"\n      aria-labelledby=\"information-dialog-title\">\n      <div class=\"information-shell\">\n        <header class=\"information-header\">\n          <div>\n            <small>Builder reference</small>\n            <h2 id=\"information-dialog-title\">Help</h2>\n          </div>\n          <button\n            id=\"information-close\"\n            class=\"dialog-close\"\n            type=\"button\"\n            aria-label=\"Close help\"\n            data-help=\"Close Help\">×</button>\n        </header>\n\n        <nav class=\"information-page-tabs\" aria-label=\"Help pages\">\n          <button\n            class=\"information-page-tab active\"\n            type=\"button\"\n            data-information-page-target=\"general\"\n            aria-selected=\"true\"\n            data-help=\"General help for the configuration builder.\">\n            <span class=\"information-page-tab-icon\" aria-hidden=\"true\">?</span>\n            <span>General</span>\n          </button>\n          <button\n            class=\"information-page-tab\"\n            type=\"button\"\n            data-information-page-target=\"technical\"\n            aria-selected=\"false\"\n            data-help=\"Detailed technical information about the runtime graph.\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n              <path d=\"M4 7h10 M4 12h16 M4 17h8\"></path>\n              <circle cx=\"17\" cy=\"7\" r=\"2\"></circle>\n              <circle cx=\"15\" cy=\"17\" r=\"2\"></circle>\n            </svg>\n            <span>Technical</span>\n          </button>\n          <button\n            class=\"information-page-tab\"\n            type=\"button\"\n            data-information-page-target=\"environment\"\n            aria-selected=\"false\"\n            data-help=\"Operating-system tools, browser requirements and .NET 10 setup.\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n              <rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"></rect>\n              <path d=\"M8 21h8M12 17v4\"></path>\n            </svg>\n            <span>Environment</span>\n          </button>\n          <button\n            class=\"information-page-tab\"\n            type=\"button\"\n            data-information-page-target=\"shortcuts\"\n            aria-selected=\"false\"\n            data-help=\"Keyboard shortcuts and navigation controls.\">\n            <span class=\"information-page-tab-icon\" aria-hidden=\"true\">⌨</span>\n            <span>Shortcuts</span>\n          </button>\n          <button\n            class=\"information-page-tab\"\n            type=\"button\"\n            data-information-page-target=\"nodes\"\n            aria-selected=\"false\"\n            data-help=\"Open the Configuration Outline and Runtime Graph node references.\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n              <rect x=\"3\" y=\"5\" width=\"7\" height=\"6\" rx=\"1.5\"></rect>\n              <rect x=\"14\" y=\"13\" width=\"7\" height=\"6\" rx=\"1.5\"></rect>\n              <path d=\"M10 8h4a3 3 0 0 1 3 3v2\"></path>\n            </svg>\n            <span>Nodes</span>\n          </button>\n        </nav>\n\n        <section class=\"information-page active\" data-information-page=\"general\">\n          <div class=\"information-layout\">\n            <nav class=\"information-nav\" aria-label=\"General help sections\">\n              <button type=\"button\" data-information-section-target=\"info-outline\">Outline</button>\n              <button type=\"button\" data-information-section-target=\"info-sections\">Section enums</button>\n              <button type=\"button\" data-information-section-target=\"info-inspector\">Properties</button>\n              <button type=\"button\" data-information-section-target=\"info-graph\">Pack into Node</button>\n              <button type=\"button\" data-information-section-target=\"info-preview\">Preview</button>\n              <button type=\"button\" data-information-section-target=\"info-projects\">Projects & storage</button>\n              <button type=\"button\" data-information-section-target=\"info-export\">Export</button>\n              <button type=\"button\" data-information-section-target=\"info-tour\">Guided tour</button>\n            </nav>\n\n            <article class=\"information-content\">\n              <section id=\"info-outline\" class=\"information-section\">\n                <span class=\"information-kicker\">Configuration Outline</span>\n                <h3>Build the settings structure</h3>\n                <p>\n                  Click a type to add it to the active section, or drag it directly\n                  into a target section. Selecting an item activates the section\n                  containing it. While dragging, moving near the top or bottom edge\n                  scrolls the page automatically.\n                </p>\n                <p>\n                  Dropping on the canvas background moves an existing item back to\n                  the root. Empty builder and inspector areas intentionally contain\n                  no instructional text so the workspace stays as large as possible.\n                </p>\n                <p>\n                  <strong>Button (Impulse)</strong> creates a real RML mod-menu\n                  button. Its menu label and button text are editable independently.\n                  After packing, the matching Start / Configuration output is a direct\n                  Impulse and can connect to every compatible impulse input.\n                </p>\n                <p>\n                  <strong>Inline row</strong> is a real Outline container. Drag two or\n                  more ordinary settings, buttons, Runtime Displays or dynamic controls\n                  into it to place them side by side. Its own horizontal overflow is an\n                  automatic scroll layer, so the existing Ctrl/Command + Wheel hierarchy\n                  and Shift + Wheel horizontal scrolling work without a special mode.\n                  Select the row to choose its default horizontal or vertical orientation.\n                  The row's own <strong>Internal / hidden</strong> property hides the\n                  complete group by default while keeping it available to runtime\n                  <strong>Set Configuration Visibility</strong> logic.\n                  Select any direct child to define its width percentage and optionally\n                  hide its left-side label. Preview, the generated RML menu and runtime\n                  graph overrides all use the same values.\n                </p>\n              </section>\n\n              <section id=\"info-sections\" class=\"information-section\">\n                <span class=\"information-kicker\">Structure</span>\n                <h3>Section enums</h3>\n                <p>\n                  A Section enum is an enum controller whose values become visible\n                  settings pages. Section enums can be nested. Their sections can be\n                  reordered horizontally and moved between containers.\n                </p>\n              </section>\n\n              <section id=\"info-inspector\" class=\"information-section\">\n                <span class=\"information-kicker\">Properties</span>\n                <h3>Settings and runtime behavior</h3>\n                <p>\n                  The Properties panel edits the selected item. Section enums normally\n                  use <strong>Stored only</strong>, because RML already handles their\n                  navigation. Numeric range validation can require a maximum value and\n                  enables the scalar slider. Hidden settings remain stored in the\n                  configuration even when they are not editable in the RML UI.\n                </p>\n                <p>\n                  Vector editors use one field per component. List-style editors use\n                  one value per line where applicable.\n                </p>\n              </section>\n\n              <section id=\"info-graph\" class=\"information-section\">\n                <span class=\"information-kicker\">Typed runtime graph</span>\n                <h3>Pack into Node</h3>\n                <p>\n                  <strong>Pack into Node</strong> replaces the visual configuration\n                  outline with an automatically synchronized typed runtime graph.\n                  Returning to the outline preserves the packed graph. Reloading restores\n                  the last open Outline or Typed Runtime Graph view together with its\n                  saved nodes and wires.\n                </p>\n                <p>\n                  The same canvas can temporarily show an embedded Custom C# editor,\n                  a Custom C# File Graph or an API Composite's internal API &amp; Logic Graph.\n                  In a nested view the main arrow returns to the immediately previous graph;\n                  in the main Runtime Graph it returns to Configuration Outline. The return\n                  entry is consumed once so repeated transitions cannot form a navigation loop.\n                </p>\n                <p>\n                  A responsive graph hierarchy trail remains visible above the graph and the\n                  embedded code editor. It shows every active level from Runtime Graph through\n                  API &amp; Logic and Custom C# File contexts to the current editor. The current\n                  level is highlighted; click any existing ancestor to return directly while\n                  all skipped child graphs are saved and closed in order. Missing graph owners,\n                  invalid API Composites and navigation cycles are never bypassed. On narrow\n                  screens the complete trail scrolls horizontally and keeps the active level\n                  in view.\n                </p>\n                <p>\n                  The Generated file selector is available in both Configuration Outline\n                  and Typed Runtime Graph. Both views expose the same live generated\n                  project manifest, but keep independent selections: the Outline defaults\n                  to the main configuration/mod source, while the graph defaults to its\n                  generated runtime-graph source. The selector updates automatically when\n                  graph nodes add, remove or rename generated outputs.\n                </p>\n              </section>\n\n              <section id=\"info-preview\" class=\"information-section\">\n                <span class=\"information-kicker\">Settings preview</span>\n                <h3>Preview behavior</h3>\n                <p>\n                  Preview changes remain session-local until applied or saved. The Full\n                  Color Picker keeps its profile and strength behavior. The adaptive\n                  color-picker fit script is loaded only on viewports that need it.\n                </p>\n                <p>\n                  Pressing an Outline Button in Preview runs the connected typed impulse\n                  path locally. Preview-safe Configuration Menu nodes immediately update\n                  visibility, order, value, Inline Row direction, child width and label\n                  visibility in this Preview. Branch, Gate, Sequence and ordinary single-output\n                  impulse forwarding are simulated; runtime-only API side effects are skipped.\n                  This never invokes the generated mod and never sends anything to Resonite.\n                </p>\n              </section>\n\n              <section id=\"info-projects\" class=\"information-section\">\n                <span class=\"information-kicker\">Local data</span>\n                <h3>Projects, autosave and privacy</h3>\n                <p>\n                  The current draft is saved automatically in this browser. A JSON\n                  project file creates a portable backup that can be reopened on this\n                  or another device. The builder runs entirely in the browser; source\n                  code and configuration data are not uploaded by the builder.\n                </p>\n              </section>\n\n              <section id=\"info-export\" class=\"information-section\">\n                <span class=\"information-kicker\">Generated project</span>\n                <h3>Export</h3>\n                <p>\n                  Generated projects target <strong>.NET 10</strong> for the current\n                  Resonite/RML setup. The Resonite installation path is used for local\n                  assembly references. MSBuild variables such as <code>$(HOME)</code>\n                  are supported, and <code>ResonitePath</code> can still be overridden\n                  when building.\n                </p>\n                <p>\n                  Multiple selected files are bundled into one ZIP. When an early\n                  Harmony patch library is present, the ZIP contains separate\n                  <code>Mod</code> and <code>Patches</code> project folders plus build\n                  scripts. Their project files deploy the compiled DLLs to\n                  <code>rml_mods</code> and <code>rml_libs</code> respectively. The\n                  Export dialog renders the exact live package manifest rather than a\n                  hard-coded list, so later generator extensions appear automatically.\n                </p>\n              </section>\n\n              <section id=\"info-tour\" class=\"information-section\">\n                <span class=\"information-kicker\">Interactive onboarding</span>\n                <h3>Guided first-steps tour</h3>\n                <p>The Tour button starts the same visual assistant that appears on the first launch. Every lesson is explained in the Step Overlay first; only Demonstrate starts one teacher-mouse run, and Replay repeats it deliberately. The assistant uses the real Outline, graph, scroll, zoom, Project, Export and Help controls, keeps the demonstrated subject visible on the current screen size and restores the snapshotted builder state when you finish or skip it.</p>\n              </section>\n            </article>\n          </div>\n        </section>\n\n        <section class=\"information-page\" data-information-page=\"technical\" hidden>\n          <div class=\"information-layout\">\n            <nav class=\"information-nav\" aria-label=\"Technical help sections\">\n              <button type=\"button\" data-information-section-target=\"info-library\">Node library</button>\n              <button type=\"button\" data-information-section-target=\"info-wires\">Sockets & wires</button>\n              <button type=\"button\" data-information-section-target=\"info-runtime\">Live runtime monitors</button>\n              <button type=\"button\" data-information-section-target=\"info-collections\">Collections & iteration</button>\n              <button type=\"button\" data-information-section-target=\"info-dynamic-controls\">Dynamic controls</button>\n              <button type=\"button\" data-information-section-target=\"info-editing\">Graph editing</button>\n              <button type=\"button\" data-information-section-target=\"info-api-composites\">API Composites</button>\n              <button type=\"button\" data-information-section-target=\"info-code-editor\">Custom C# editor</button>\n              <button type=\"button\" data-information-section-target=\"info-code-diagnostics\">Diagnostics</button>\n              <button type=\"button\" data-information-section-target=\"info-harmony\">Harmony projects</button>\n              <button type=\"button\" data-information-section-target=\"info-advanced\">Advanced / Raw C#</button>\n            </nav>\n\n            <article class=\"information-content\">\n              <section id=\"info-library\" class=\"information-section\">\n                <span class=\"information-kicker\">Node library</span>\n                <h3>Browsable and searchable API catalog</h3>\n                <p>\n                  Every live Resonite API category and its complete count is always\n                  listed in the Node Library and starts collapsed. Opening a category\n                  creates its node cards in bounded batches instead of mounting the\n                  complete catalog at once. Enter at least two characters in Node Search\n                  for the fastest direct lookup. Search results are capped; refine broad\n                  searches when necessary.\n                </p>\n              </section>\n\n              <section id=\"info-wires\" class=\"information-section\">\n                <span class=\"information-kicker\">Typed connections</span>\n                <h3>Configuration sockets and wires</h3>\n                <div class=\"information-symbol-grid\">\n                  <span><b>●</b> Stored value</span>\n                  <span><b>▶</b> Startup</span>\n                  <span><b>■</b> Saved</span>\n                  <span><b>◆</b> Startup + saved</span>\n                  <span><b>⚡</b> Button press impulse</span>\n                </div>\n                <p>\n                  Wire colors represent value types. Startup and Saved configuration\n                  sockets can connect to matching value inputs and impulse inputs;\n                  Stored sockets remain value-only. Incompatible sockets are disabled\n                  while a connection is being created.\n                </p>\n                <p>\n                  A Button socket is already an Impulse source: each press in the RML\n                  configuration page emits exactly one pulse. It does not depend on Save\n                  Settings and does not use Startup/Saved reaction modes.\n                </p>\n                <p>\n                  Dropping an output wire on empty graph space creates a monitor.\n                  Dropping a value-input wire can create a self-contained constant or\n                  context source. Impulse inputs and multi-input runtime operations must\n                  be connected explicitly.\n                </p>\n              </section>\n\n              <section id=\"info-runtime\" class=\"information-section\">\n                <span class=\"information-kicker\">Scanner runtime bridge</span>\n                <h3>Live Display Value and Display Impulse</h3>\n                <p>\n                  Display Value and Display Impulse prefer values published by the matching\n                  generated mod running inside Resonite. The generated runtime discovers the\n                  scanner mod without a compile-time dependency, and the scanner streams each\n                  monitor update to this builder over its local loopback SSE bridge.\n                </p>\n                <p>\n                  Matching uses the generated namespace/class channel plus the stable graph node\n                  id. After adding, deleting or replacing a monitor, rebuild and reload the\n                  generated mod. When the scanner or matching mod is unavailable, the node clearly\n                  falls back to <strong>Runtime Only</strong> and keeps the existing local graph\n                  preview where that value can be evaluated safely.\n                </p>\n                <p>\n                  Add <strong>Display Value (RML Menu)</strong> in Configuration Outline,\n                  then pack the outline. That item appears as its own dedicated output on the\n                  <strong>Start</strong> node. Every graph <strong>Display Value</strong> has a second\n                  <strong>RML Menu</strong> input. One Start-node display output may fan out to\n                  <strong>multiple</strong> Display Value or Display Impulse nodes. Display Impulse has the same optional <strong>RML Menu</strong> input and contributes its live pulse counter. By default, every connected runtime value\n                  stays side by side in <strong>one single RML menu row</strong>; the row does not wrap values\n                  into a vertical list. Select the Display Value (RML Menu) item in Properties to set\n                  their left-to-right order. If a vertical list is actually wanted, enable\n                  <strong>Stack values vertically</strong> there; the same order controls top-to-bottom\n                  placement in that mode. The graph wires define membership and the inspector defines\n                  presentation—there is no source dropdown.\n                </p>\n              </section>\n\n\n              <section id=\"info-collections\" class=\"information-section\">\n                <span class=\"information-kicker\">Typed collections</span>\n                <h3>For Each, Collect To List and indexed access</h3>\n                <p>\n                  <strong>For Each</strong> accepts any scanner-derived or built-in type\n                  that implements <code>System.Collections.IEnumerable</code>. Its\n                  collection and item generics are linked: connecting a typed collection\n                  automatically infers the exact element type, while the zero-based\n                  <strong>Index</strong> and current <strong>Item</strong> remain valid for\n                  the duration of each <strong>Body</strong> impulse. <strong>Completed</strong>\n                  fires after the final item and also for empty or null collections.\n                </p>\n                <p>\n                  Example: <code>Focused World → Get · World.AllUsers → For Each</code>,\n                  then connect <code>Item</code> to a User property such as\n                  <code>Get · User.UserName</code> and run logging or other logic from\n                  <code>Body</code>. Arrays, generic lists, dictionary key/value collections\n                  and custom catalog types implementing <code>IEnumerable&lt;T&gt;</code>\n                  use the same node. Asynchronous enumerables are intentionally separate\n                  and are not executed by this synchronous node.\n                </p>\n                <p>\n                  <strong>Get Item At Index</strong> reads one zero-based item from any\n                  synchronous typed collection. Its Collection and Item generics are linked\n                  exactly, so <code>List&lt;User&gt;</code> produces <code>User</code> and\n                  <code>List&lt;string&gt;</code> produces <code>string</code>. Item returns\n                  the type default for an invalid index, while Success reports validity and\n                  Count exposes the current collection size.\n                </p>\n                <p>\n                  <strong>Collect To List</strong> is a separate stateful collection node.\n                  <strong>Reset</strong> clears its strongly typed <code>List&lt;T&gt;</code>,\n                  <strong>Add</strong> appends the current <strong>Value</strong>, and the\n                  <strong>List</strong> and <strong>Count</strong> outputs expose the complete\n                  current result. For a fresh scan, connect the trigger to\n                  <code>Reset</code>, <code>Reset Done</code> to <code>For Each.Call</code>,\n                  <code>For Each.Body</code> to <code>Add</code>, and the per-item mapped\n                  value to <code>Value</code>. The List output can feed Display Value,\n                  another For Each node, object inputs and compatible standard .NET\n                   collection-interface inputs. If one impulse output fans out to several\n                   direct Reset or Add targets, the generated runtime performs every direct\n                   sibling mutation first and only then follows their Reset Done / Added\n                   continuation paths. A later sibling reset therefore cannot erase values\n                   produced by an earlier continuation loop.\n                </p>\n              </section>\n\n\n              <section id=\"info-dynamic-controls\" class=\"information-section\">\n                <span class=\"information-kicker\">Dynamic configuration controls</span>\n                <h3>Collection-backed controls from the runtime graph</h3>\n                <p><strong>Mark as Editable</strong> on <strong>Collect To List</strong> exposes a generated Dynamic Choice entry in the Configuration Outline node palette. It does not insert a setting merely when enabled. If it is later switched back to <strong>false</strong>, any Dynamic Choice previously materialized from that exact collection is removed from Configuration Outline automatically, because the collection is no longer an editable RML source.</p>\n                <p>Click or drag that generated palette node into the exact Outline position you want. Only then is the dynamic setting created and, after packing, exposed on the Start / Configuration node. The Dynamic Choice binds directly to the marked Collect To List source: no Display Value/helper node and no separate Labels/Stable Values source selection is required. Because that collection exists only at runtime, Properties only offers a Default selection while the matching generated mod is actually running and its runtime list is available. The Builder subscribes to that runtime channel directly, so Properties and Preview update as soon as the list arrives or changes; no unrelated click or rerender is required. Without an explicit valid default, the first runtime item is selected automatically (unless Allow empty selection is enabled). The generated Start-node string output resolves to that same effective selection as soon as the collection changes, so graph logic never remains on an empty raw configuration value while the menu already shows a valid first item. It can be wired freely into Equal, Select, Branch/flow logic, method calls, stores, or any other compatible typed runtime logic. Dynamic controls retain their exact global Configuration Outline position among ordinary settings and Runtime Display rows.</p>\n              </section>\n\n              <section id=\"info-editing\" class=\"information-section\">\n                <span class=\"information-kicker\">Graph interaction</span>\n                <h3>Move, resize and route</h3>\n                <p>\n                  Drag nodes to move them. Resize from the right edge, bottom edge or\n                  lower-right corner. Double-click a resize grip to reset that axis.\n                  Wires can contain movable bend points and branches. The graph toolbar\n                  can center the graph or clear operator nodes while retaining the\n                  packed configuration node.\n                </p>\n                <p>\n                  Explicit scroll-layer selection works throughout the whole builder,\n                  not only inside the runtime graph. Hold <strong>Ctrl</strong> (Command\n                  on macOS) and use the wheel to choose a level. The hierarchy is captured\n                  from the first gesture and remains frozen while the modifier is held:\n                  moving the mouse into Properties, Generated Project Files, another node\n                  or a dialog does not replace that hierarchy. A new session starts at the\n                  outermost available level. From there, the selectable hierarchy follows visual\n                  reading order: the real visual hierarchy: each parent is visited before its descendants. Sibling or independent regions are read\n                  top to bottom and, when they share a row, left to right. A region is completed depth-first before the selector moves to a later sibling region below. Wheel down advances through that order and\n                  Wheel up walks it backward. The selector has no hard beginning or end:\n                  continuing in the same direction wraps around to the opposite end and repeats the hierarchy.\n                  The currently previewed boundary itself glows; no separate corner status\n                  box is shown. Releasing the modifier enables a <strong>global scroll\n                  override</strong>. Every subsequent Wheel event is\n                  captured before nested panels and native browser scrolling, and is routed\n                  only to the locked level regardless of cursor position. Shift does not\n                  release the selection/override only when that exact selected level has a\n                  real horizontal scroll axis; Shift + Wheel then scrolls that same level\n                  horizontally. On a level without horizontal scrolling, Shift releases the\n                  selection/override like any other non-Ctrl/Command key. Any other key\n                  (including Tab, Escape, Enter, arrows or text input) and any pointer press\n                  (mouse, touch or pen; any mouse button) releases it without consuming the\n                  original input. Reaching an edge, becoming empty, or being\n                  temporarily rerendered never silently transfers scrolling to another level.\n                  Only layers with a genuinely visible, unobscured area participate: elements\n                  outside the viewport or fully covered by a higher stacking layer (for example\n                  underneath the sticky header, a dialog or an overlay) are excluded. Partially\n                  covered layers remain selectable through their still-visible area.\n                </p>\n                <p>\n                  The final outermost level is always the actual\n                  <code>&lt;html&gt;</code> element. Inside the Typed Runtime Graph the\n                  virtual <strong>Graph ROOT</strong> therefore appears one level before\n                  <code>&lt;html&gt;</code>, rather than replacing the page root. The\n                  <code>&lt;html&gt;</code> level remains selectable even when it has no\n                  overflow; in that case it is shown as an empty level. If a browser uses\n                  a different <code>document.scrollingElement</code>, that real document\n                  scroll surface is inserted immediately inside the still-present empty\n                  <code>&lt;html&gt;</code> level.\n                </p>\n                <p>\n                  The level list is not a hard-coded set of panels. A new selection\n                  session is built from the current composed DOM path and real overflow\n                  dimensions, then locked by stable identities so dynamically rerendered\n                  elements can rebind without changing the chosen level. Dynamically rendered\n                  nested Section enums, real scrollable graph-node bodies, dialog lists and\n                  future scroll containers therefore participate automatically. A future custom surface can\n                  also declare\n                  <code>data-rml-scroll-layer=\"auto\"</code> (or\n                  <code>\"always\"</code> for an intentionally selectable empty level) and a\n                  stable <code>data-rml-scroll-layer-key</code> without changing the selector.\n                </p>\n              </section>\n\n              <section id=\"info-api-composites\" class=\"information-section\">\n                <span class=\"information-kicker\">Reusable API &amp; logic graphs</span>\n                <h3>API Composites and Saved API Composites</h3>\n                <p>\n                  Select at least two compatible graph nodes with Ctrl/Command-click,\n                  including at least one verified scanner-catalog API node, then choose\n                  <strong>Create API Composite</strong> in Properties. The Composite keeps\n                  node placement, typed contracts, wires, bend points and branches. Open\n                  <strong>Edit Internal API &amp; Logic Graph</strong> to continue editing it;\n                  unconnected ports of newly added internal nodes are exposed on the outer\n                  Composite automatically. The final verified catalog API node cannot be\n                  removed, because every API Composite must retain at least one.\n                </p>\n                <p>\n                  The internal graph accepts verified API nodes, supported value, math,\n                  conversion, flow and output nodes, plus the same hybrid\n                  <strong>Custom C#</strong>, <strong>C# Project</strong> and\n                  <strong>C# Reference</strong> nodes used in the Runtime Graph. Custom C#\n                  keeps one palette node with File, Action, Expression, Runtime Graph Member\n                  and Main Mod Member modes; no redundant mode-specific palette copies are\n                  created. Roslyn syntax, token, trivia and Custom C# File Output nodes remain\n                  exclusive to a Custom C# File Graph.\n                </p>\n                <p>\n                  Use <strong>Save to Saved API Composites</strong>,\n                  <strong>Update Saved Composite</strong> or <strong>Save as New Composite</strong>\n                  to reuse the complete internal graph. Saved Composites can be inserted from\n                  the Node Library, unpacked, deleted, exported and imported as JSON, and are\n                  checked individually against the active verified catalog. Existing placed\n                  instances remain complete when a library template is deleted. Owned Custom\n                  C# File Graphs and their source are included in project save, Composite save,\n                  export, import, unpacking, migration and generated-code expansion.\n                </p>\n              </section>\n\n              <section id=\"info-code-editor\" class=\"information-section\">\n                <span class=\"information-kicker\">Custom C# workbench</span>\n                <h3>Embedded editor, floating overlay and node insertion</h3>\n                <p>\n                  Opening a Custom C# code field first shows the large editor embedded in\n                  place of the current graph. The main back-arrow returns to the immediately\n                  previous graph; from the main Runtime Graph it returns to Configuration\n                  Outline. Each return entry is consumed once, so opening nested graphs and\n                  editors cannot create a closed navigation loop. Any action that replaces a\n                  Runtime Graph also replaces an embedded editor in the same way, and returning\n                  restores the correct previous view.\n                </p>\n                <p>\n                  Only the embedded editor shows the JavaScript presentation dropdown used\n                  throughout the Builder. It contains exactly the two destinations\n                  <strong>Overlay</strong> and <strong>Separate Window</strong>; Embedded is\n                  the current view and is therefore not listed as a destination. Overlay keeps the movable application\n                  window with Return to embedded editor, Minimize/Restore, Maximize/Restore\n                  and Close in its title bar. Separate Window always opens a real native browser\n                  popup in Chromium, Firefox and Safari so the editor can be placed on another\n                  monitor. Its single operating-system/browser title bar is the only place for\n                  Minimize, Maximize/Restore and Close; the editor draws no duplicate window\n                  controls and never simulates maximization by resizing itself. The editor header\n                  adds only Return to embedded editor. Source, diagnostics, selection and the\n                  Inspector draft remain synchronized throughout the host change. Overlay and Separate Window\n                  never show another presentation dropdown: their return control always\n                  goes directly back to Embedded. The normal page-area hide/show control also\n                  appears only in the embedded editor and remains synchronized with the Runtime\n                  Graph.\n                </p>\n                <p>\n                  The large editor and the small Properties code field synchronize in both\n                  directions on every input, including after selecting other nodes and returning,\n                  or after moving the editor between embedded and overlay presentation. Click a\n                  compatible node in the left palette while an editor is active, drag a palette\n                  node onto the editor, or drag an existing graph node onto it to insert the\n                  node's C# representation at the caret. Unsupported nodes are rejected without\n                  changing their graph position or source.\n                </p>\n                <p>\n                  Find, Replace and Settings are real toggle buttons: their pressed state is\n                  visible, a second click closes the same panel, and opening one closes the\n                  conflicting panel. Find supports Match Case, Whole Word and Regular Expression,\n                  previous/next navigation, Replace and Replace All. Every active match is the\n                  textarea's real focused forward selection, not a visual overlay, so navigation\n                  and replacement leave the exact source range selected.\n                </p>\n              </section>\n\n              <section id=\"info-code-diagnostics\" class=\"information-section\">\n                <span class=\"information-kicker\">Live debug &amp; problems</span>\n                <h3>Builder and Roslyn are separate output sources</h3>\n                <p>\n                  In Editor Settings choose either <strong>Builder</strong> or\n                  <strong>Roslyn</strong>. Debug and Problems render only the selected source;\n                  the other source remains available but is never mixed into the visible list.\n                  Builder reports generation, synchronization and worker activity. Roslyn reports\n                  live C# 14 syntax diagnostics. Switching sources redraws both views immediately.\n                </p>\n                <p>\n                  Diagnostics refresh while code is typed and after editor/graph synchronization.\n                  If the same error occurs again, its newest occurrence replaces the older visible\n                  record with a fresh monotonic millisecond timestamp instead of being discarded as\n                  a duplicate. This applies independently to Builder and Roslyn, so repeated status\n                  and error messages always show when they most recently occurred.\n                </p>\n              </section>\n\n              <section id=\"info-harmony\" class=\"information-section\">\n                <span class=\"information-kicker\">Harmony load phases</span>\n                <h3>Main mod patches and early rml_libs patches</h3>\n                <p>\n                  <strong>Harmony Patch Event</strong>, lifecycle patch presets and\n                  scanner-generated Harmony API calls stay in the main mod project.\n                  They are registered when the mod reaches <code>OnEngineInit</code>,\n                  because their callbacks may emit graph impulses and access generated\n                  runtime state.\n                </p>\n                <p>\n                  <strong>Harmony Exact Patch Source</strong> also stays in the main\n                  project, but its attribute patches are now registered automatically\n                  with one guarded <code>PatchAll</code> call. Use\n                  <strong>Early Harmony Patch Library (rml_libs)</strong> only when a\n                  patch must be active before normal <code>rml_mods</code> are loaded.\n                  That node creates an independent project and DLL and cannot depend on\n                  graph sockets or main-mod configuration state. It can only target\n                  assemblies already available before <code>rml_mods</code> are loaded;\n                  patches for another normal mod belong in the main mod phase. Automatic\n                  discovery of the early DLL requires the matching special Builder-compatible\n                  Mod Loader build containing the generated-library marker support.\n                </p>\n                <p>\n                  Low-level HarmonyLib nodes produced by the API scanner are kept under\n                  Advanced / Raw C#. They expose the scanned API but do not infer patch\n                  signatures, callback methods or load phase automatically.\n                </p>\n              </section>\n\n              <section id=\"info-advanced\" class=\"information-section\">\n                <span class=\"information-kicker\">Expert fallback</span>\n                <h3>Advanced / Raw C# and the hybrid Custom C# node</h3>\n                <p>\n                  Manual usings, references, source files, compiler overrides and\n                  reflection-oriented fallback nodes stay hidden unless\n                  <strong>Show Advanced / Raw C#</strong> is enabled. Prefer normal\n                  typed catalog nodes whenever a direct node exists.\n                </p>\n                <p>\n                  <strong>Custom C#</strong> itself is one hybrid node, not five separate\n                  palette entries. File mode owns a persistent visual C# File Graph;\n                  Action and Expression expose typed graph ports; Runtime Graph Member and\n                  Main Mod Member emit complete member declarations into their respective\n                  generated classes. <strong>C# Project</strong> defines an optional compiled\n                  project and <strong>C# Reference</strong> switches between Assembly, NuGet\n                  Package and Framework references. These three nodes are also supported\n                  inside an API &amp; Logic Graph.\n                </p>\n                <p>\n                  Opening File mode's Node Graph exposes the isolated C# 14/Roslyn syntax\n                  library and its Custom C# File Output. Those syntax-building nodes never\n                  appear in the main Runtime Graph or directly in an API &amp; Logic Graph.\n                  The Nodes page marks every restricted node and builds the complete fixed\n                  registry reference at runtime, including palette-hidden helpers.\n                </p>\n              </section>\n            </article>\n          </div>\n        </section>\n\n\n        <section class=\"information-page\" data-information-page=\"environment\" hidden>\n          <div class=\"information-layout information-shortcuts-layout\">\n            <nav class=\"information-nav\" aria-label=\"Environment sections\">\n              <button type=\"button\" data-information-section-target=\"environment-overview\">Required vs optional</button>\n              <button type=\"button\" data-information-section-target=\"environment-runtime\">Run generated mods</button>\n              <button type=\"button\" data-information-section-target=\"environment-dotnet\">Build generated mods</button>\n              <button type=\"button\" data-information-section-target=\"environment-catalog\">Live API catalog</button>\n              <button type=\"button\" data-information-section-target=\"environment-tools\">Optional tools</button>\n              <button type=\"button\" data-information-section-target=\"environment-windows\">Windows</button>\n              <button type=\"button\" data-information-section-target=\"environment-macos\">macOS</button>\n              <button type=\"button\" data-information-section-target=\"environment-linux\">Linux</button>\n              <button type=\"button\" data-information-section-target=\"environment-browser\">Browser</button>\n            </nav>\n            <article class=\"information-content\">\n              <section id=\"environment-overview\" class=\"information-section\">\n                <span class=\"information-kicker\">Builder environment</span>\n                <h3>Required, conditionally required and optional</h3>\n                <p>\n                  The web Builder, the generated project toolchain and the Resonite runtime\n                  are separate layers. Install only the layer needed for the intended task.\n                </p>\n                <div class=\"shortcut-grid\">\n                  <div>\n                    <kbd>Required</kbd>\n                    <span>To run a compiled Builder mod: a compatible 64-bit Resonite installation, the special Builder-compatible Mod Loader and dependencies supplied by the Builder author, and the generated mod DLL plus its exported library dependencies.</span>\n                  </div>\n                  <div>\n                    <kbd>Build</kbd>\n                    <span>Additionally required to compile a Builder export: the .NET 10 SDK and access to the matching Resonite and special-loader reference assemblies selected by the generated project.</span>\n                  </div>\n                  <div>\n                    <kbd>Conditional</kbd>\n                    <span>The live Scanner is required only when a project imports, validates or exports version-derived Resonite, FrooxEngine or Harmony API catalog nodes.</span>\n                  </div>\n                  <div>\n                    <kbd>Optional</kbd>\n                    <span>Window-pinning utilities, Git and an external IDE can improve the workflow but are not required by the generated mod.</span>\n                  </div>\n                </div>\n              </section>\n\n              <section id=\"environment-runtime\" class=\"information-section\">\n                <span class=\"information-kicker\">Required to use generated mods</span>\n                <h3>Resonite, the private Builder loader and exported DLLs</h3>\n                <p>\n                  Install a compatible 64-bit copy of\n                  <a href=\"https://store.steampowered.com/app/2519830/Resonite/\" target=\"_blank\" rel=\"noopener noreferrer\">Resonite</a>.\n                  The officially published minimum desktop requirements currently start at\n                  Windows 10, a dual-core CPU, 8 GB RAM, a GTX 750-class GPU, DirectX 11,\n                  broadband internet and 2 GB free storage; VR needs additional headroom.\n                </p>\n                <p>\n                  Use only the exact special Builder-compatible Mod Loader package supplied\n                  privately by the Builder author through a Discord Direct Message. Install\n                  every dependency included with that package and use its supplied launch\n                  configuration. Do <strong>not</strong> replace or update it with the public\n                  standard loader, Resolute or another generic mod manager; those versions can\n                  be incompatible with Builder-generated functionality.\n                </p>\n                <p>\n                  Place the generated mod assembly in <code>rml_mods</code>, and place exported\n                  non-framework dependency assemblies in <code>rml_libs</code>. Start Resonite\n                  and verify the special loader and mod entries in the Resonite logs. Loader\n                  updates must come from the Builder author through the same private Discord\n                  Direct Message distribution path.\n                </p>\n                <p>\n                  The special loader already provides its own settings page. An external\n                  settings mod such as ResoniteModSettings is not required and must not be\n                  assumed compatible unless the Builder author's documentation explicitly\n                  confirms the exact combination.\n                </p>\n                <p>\n                  Someone who only installs an already compiled mod does <strong>not</strong>\n                  need the .NET SDK, a source-code editor, Git, the Builder Scanner or a\n                  window-pinning utility. There is intentionally no public loader download\n                  link here because the Builder requires its privately supplied version.\n                </p>\n              </section>\n\n              <section id=\"environment-dotnet\" class=\"information-section\">\n                <span class=\"information-kicker\">Required to compile Builder exports</span>\n                <h3>Install the .NET 10 SDK and resolve game references</h3>\n                <p>\n                  Building an exported <code>net10.0</code> project locally requires the\n                  <strong>.NET 10 SDK</strong>. The runtime alone can execute compatible\n                  applications but cannot compile the generated project. Installing the SDK\n                  also installs its matching runtime, so a separate runtime installation is\n                  normally unnecessary.\n                </p>\n                <div class=\"shortcut-grid\">\n                  <div>\n                    <kbd>Windows</kbd>\n                    <span>Run <code>winget install Microsoft.DotNet.SDK.10</code>, or use the <a href=\"https://learn.microsoft.com/dotnet/core/install/windows\" target=\"_blank\" rel=\"noopener noreferrer\">official Windows instructions</a>.</span>\n                  </div>\n                  <div>\n                    <kbd>macOS</kbd>\n                    <span>Use the Microsoft installer matching Apple silicon (Arm64) or Intel (x64): <a href=\"https://learn.microsoft.com/dotnet/core/install/macos\" target=\"_blank\" rel=\"noopener noreferrer\">Install .NET on macOS</a>.</span>\n                  </div>\n                  <div>\n                    <kbd>Linux</kbd>\n                    <span>Use the package instructions for the installed distribution: <a href=\"https://learn.microsoft.com/dotnet/core/install/linux\" target=\"_blank\" rel=\"noopener noreferrer\">Install .NET on Linux</a>.</span>\n                  </div>\n                  <div>\n                    <kbd>Verify</kbd>\n                    <span>Open a new terminal and run <code>dotnet --list-sdks</code>. At least one line must begin with <code>10.0.</code>; use <code>dotnet --info</code> when diagnosing architecture or path problems.</span>\n                  </div>\n                </div>\n                <p>\n                  Direct installers for all supported systems and architectures are also\n                  available on the <a href=\"https://dotnet.microsoft.com/download/dotnet/10.0\" target=\"_blank\" rel=\"noopener noreferrer\">official .NET 10 download page</a>.\n                </p>\n                <p>\n                  The generated project must also resolve the Resonite, FrooxEngine,\n                  Elements.Core and special Builder-compatible Mod Loader assemblies it\n                  references. Keep the\n                  generated project beside the exported <code>rml_mods</code> and\n                  <code>rml_libs</code> structure, or set its documented\n                  <code>ResonitePath</code> override to the correct local installation before\n                  running <code>dotnet build</code>.\n                </p>\n              </section>\n\n              <section id=\"environment-catalog\" class=\"information-section\">\n                <span class=\"information-kicker\">Conditionally required</span>\n                <h3>Use the live Scanner for version-derived API nodes</h3>\n                <p>\n                  The fixed Builder nodes, Configuration Outline, Custom C# editing and\n                  projects without catalog-derived API nodes do not require a Scanner.\n                  A live compatible Scanner becomes mandatory when the project uses the\n                  generated Resonite, FrooxEngine or Harmony API catalog: the Builder verifies\n                  the running installation's semantic catalog and fingerprint before import,\n                  replacement or export. A cached catalog is useful for display but is not a\n                  substitute for live verification when those API contracts must be emitted.\n                </p>\n                <p>\n                  Start the Scanner supplied for the Builder environment, keep its local\n                  health endpoint reachable, and wait for the Builder's catalog source to show\n                  a verified live state. Do not expose the Scanner port to the internet; it is\n                  a local development companion rather than a public service.\n                </p>\n              </section>\n\n              <section id=\"environment-tools\" class=\"information-section\">\n                <span class=\"information-kicker\">Optional workflow tools</span>\n                <h3>Install only what improves the chosen workflow</h3>\n                <div class=\"shortcut-grid\">\n                  <div>\n                    <kbd>Source</kbd>\n                    <span><a href=\"https://git-scm.com/downloads\" target=\"_blank\" rel=\"noopener noreferrer\">Git</a> is recommended for version history and sharing generated projects, but exported DLLs do not depend on it.</span>\n                  </div>\n                  <div>\n                    <kbd>Editor</kbd>\n                    <span><a href=\"https://code.visualstudio.com/Download\" target=\"_blank\" rel=\"noopener noreferrer\">Visual Studio Code</a>, <a href=\"https://visualstudio.microsoft.com/downloads/\" target=\"_blank\" rel=\"noopener noreferrer\">Visual Studio</a> or <a href=\"https://www.jetbrains.com/rider/download/\" target=\"_blank\" rel=\"noopener noreferrer\">JetBrains Rider</a> can inspect and debug generated C#; the Builder's own editor remains sufficient for graph and Custom C# editing.</span>\n                  </div>\n                  <div>\n                    <kbd>Windows</kbd>\n                    <span>Microsoft PowerToys can pin the separate code editor system-wide. The Builder Overlay provides the no-install alternative.</span>\n                  </div>\n                  <div>\n                    <kbd>macOS/Linux</kbd>\n                    <span>Use the platform-specific window tools documented below only when the separate editor must remain above other applications.</span>\n                  </div>\n                </div>\n              </section>\n\n              <section id=\"environment-windows\" class=\"information-section\">\n                <span class=\"information-kicker\">Windows 10 / 11</span>\n                <h3>Pin the separate editor with PowerToys</h3>\n                <p>\n                  Microsoft PowerToys provides the system-level Always On Top function.\n                  Focus the separate editor and press <kbd>Win</kbd> + <kbd>Ctrl</kbd> +\n                  <kbd>T</kbd>. Press the same shortcut again to unpin it. The optional border,\n                  sound and shortcut can be changed in PowerToys settings.\n                </p>\n                <p>\n                  <a href=\"https://learn.microsoft.com/windows/powertoys/always-on-top\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft PowerToys · Always On Top</a>\n                </p>\n              </section>\n\n              <section id=\"environment-macos\" class=\"information-section\">\n                <span class=\"information-kicker\">macOS</span>\n                <h3>Use Overlay, Split View or optional window pinning</h3>\n                <p>\n                  macOS has no universal built-in Always On Top switch for arbitrary browser\n                  windows. Use the Builder Overlay for guaranteed in-tab priority, or place\n                  the Builder and separate editor side by side with\n                  <a href=\"https://support.apple.com/guide/mac-help/use-apps-in-split-view-mchl4fbe2921/mac\" target=\"_blank\" rel=\"noopener noreferrer\">Apple Split View</a>.\n                </p>\n                <p>\n                  Users who specifically need system-wide pinning can evaluate a third-party\n                  window utility such as\n                  <a href=\"https://apps.apple.com/app/windowpin-window-top/id6739672480?mt=12\" target=\"_blank\" rel=\"noopener noreferrer\">WindowPin on the Mac App Store</a>.\n                  This is optional third-party software, not a Builder dependency.\n                </p>\n                <p>\n                  The web Builder and the .NET 10 SDK can be used on macOS for authoring and\n                  compilation. Running the resulting mod still requires an operating system,\n                  Resonite installation and mod-loader combination supported by those runtime\n                  projects; a window utility does not change that runtime compatibility.\n                </p>\n              </section>\n\n              <section id=\"environment-linux\" class=\"information-section\">\n                <span class=\"information-kicker\">Linux desktops</span>\n                <h3>Use the desktop environment's window rule</h3>\n                <p>\n                  On KDE Plasma, use <strong>Keep Above</strong> from the window menu or create\n                  a KWin rule for the editor window. KDE documents the corresponding\n                  <a href=\"https://docs.kde.org/stable_kf6/en/kwin/kcontrol/windowspecific/attributes.html\" target=\"_blank\" rel=\"noopener noreferrer\">Keep above window attribute</a>.\n                </p>\n                <p>\n                  GNOME users can use the desktop's available window action or the optional\n                  <a href=\"https://extensions.gnome.org/extension/6619/window-on-top/\" target=\"_blank\" rel=\"noopener noreferrer\">Window on Top GNOME extension</a>.\n                  Under X11, <code>wmctrl -r :ACTIVE: -b toggle,above</code> can toggle the\n                  active EWMH-compatible window. Under Wayland the compositor controls this\n                  capability, so KDE/GNOME window actions are preferable to X11 commands.\n                </p>\n                <p>\n                  The Builder and .NET 10 SDK are cross-platform, but running Resonite and\n                  the special Builder-compatible Mod Loader on Linux must follow the private\n                  package's compatibility notes and the selected Steam compatibility setup.\n                  Verify the loader logs before treating a generated mod failure as a Builder\n                  failure.\n                </p>\n              </section>\n\n              <section id=\"environment-browser\" class=\"information-section\">\n                <span class=\"information-kicker\">Chrome, Edge, Firefox & Safari</span>\n                <h3>Allow pop-ups for Separate Window</h3>\n                <p>\n                  Use a current Chrome, Edge, Firefox or Safari release with JavaScript,\n                  WebAssembly, browser storage and file downloads enabled. These capabilities\n                  are required for the complete Builder workflow; pop-up permission is needed\n                  only for Separate Window.\n                </p>\n                <p>\n                  Separate Window uses a normal browser popup. If nothing opens, allow pop-ups\n                  for the Builder site and try again. The editor does not request\n                  Picture-in-Picture, simulate maximization or draw a second set of native\n                  window controls. Search, diagnostics, settings, node insertion and the small\n                  Inspector code field remain synchronized in Embedded, Overlay and Separate\n                  Window modes.\n                </p>\n                <p>\n                  Browser and operating-system window behavior can differ. Overlay remains the\n                  portable fallback whenever pop-ups, multiple displays or desktop pinning are\n                  unavailable; Separate Window remains the practical choice for placing the\n                  editor on a second display.\n                </p>\n              </section>\n            </article>\n          </div>\n        </section>\n\n\n        <section class=\"information-page\" data-information-page=\"shortcuts\" hidden>\n          <div class=\"information-layout information-shortcuts-layout\">\n            <nav class=\"information-nav\" aria-label=\"Shortcut sections\">\n              <button type=\"button\" data-information-section-target=\"shortcut-global\">Global</button>\n              <button type=\"button\" data-information-section-target=\"shortcut-graph\">Node graph</button>\n              <button type=\"button\" data-information-section-target=\"shortcut-code-editor\">Code editor</button>\n              <button type=\"button\" data-information-section-target=\"shortcut-search\">Search & menus</button>\n              <button type=\"button\" data-information-section-target=\"shortcut-color\">Color picker</button>\n            </nav>\n            <article class=\"information-content\">\n              <section id=\"shortcut-global\" class=\"information-section\">\n                <span class=\"information-kicker\">Global</span>\n                <h3>Keyboard & wheel shortcuts</h3>\n                <div class=\"shortcut-grid\">\n                  <div><kbd>Esc</kbd><span>Cancel an active Outline drag and restore the scroll position from before the drag.</span></div>\n                  <div><kbd>Wheel</kbd><span>Scroll the innermost visible scrollable level under the pointer. If a global level is locked, Wheel scrolls only that locked level.</span></div>\n                  <div><kbd>Ctrl</kbd><span class=\"shortcut-plus\">+</span><kbd>Wheel</kbd><span>Select visible scroll levels in reading hierarchy: start at the outermost level, then follow the real layout like reading a page: parent before descendants, then sibling regions top to bottom and same-row siblings left to right; each region is completed depth-first before moving on. Wheel down advances; Wheel up goes backward. There is no hard beginning or end: keep scrolling in the same direction and the hierarchy wraps around and repeats. Release Ctrl to lock the glowing level. Press Ctrl again later to capture the currently visible hierarchy again without clicking first. Use Command on macOS.</span></div>\n                  <div><kbd>Shift</kbd><span class=\"shortcut-plus\">+</span><kbd>Wheel</kbd><span>Scroll the locked level horizontally only when that selected level actually has a horizontal scroll axis. In that case Shift does not release the lock; otherwise Shift releases it like any other non-Ctrl/Command key.</span></div>\n                </div>\n              </section>\n              <section id=\"shortcut-graph\" class=\"information-section\">\n                <span class=\"information-kicker\">Typed node graph</span>\n                <h3>Editing shortcuts</h3>\n                <div class=\"shortcut-grid\">\n                  <div><kbd>Esc</kbd><span>Cancel the current node, wire, bend-point or palette interaction.</span></div>\n                  <div><kbd>Delete</kbd><span>Delete the selected graph node, wire or bend point.</span></div>\n                  <div><kbd>Backspace</kbd><span>Same as Delete when focus is not inside an editable field.</span></div>\n                  <div><kbd>Ctrl</kbd><span class=\"shortcut-plus\">+</span><kbd>0</kbd><span>Center the graph. On macOS use Command + 0.</span></div>\n                </div>\n              </section>\n              <section id=\"shortcut-code-editor\" class=\"information-section\">\n                <span class=\"information-kicker\">Custom C# code editor</span>\n                <h3>Find, replace and indentation</h3>\n                <div class=\"shortcut-grid\">\n                  <div><kbd>Ctrl</kbd><span class=\"shortcut-plus\">+</span><kbd>F</kbd><span>Open Find. On macOS use Command + F. The Find toolbar button itself toggles the panel closed on a second click.</span></div>\n                  <div><kbd>Ctrl</kbd><span class=\"shortcut-plus\">+</span><kbd>H</kbd><span>Open Find and Replace. On macOS use Command + Option + F. The Replace toolbar button toggles it closed on a second click.</span></div>\n                  <div><kbd>F3</kbd><span>Open Find when closed, otherwise select the next match in the editor.</span></div>\n                  <div><kbd>Shift</kbd><span class=\"shortcut-plus\">+</span><kbd>F3</kbd><span>Select the previous match.</span></div>\n                  <div><kbd>Enter</kbd><span>In the Find field, select the next match; use Shift + Enter for the previous match.</span></div>\n                  <div><kbd>Enter</kbd><span>In the Replace field, replace the currently selected match.</span></div>\n                  <div><kbd>Esc</kbd><span>Close Editor Settings first, or close Find/Replace when Settings is not open.</span></div>\n                  <div><kbd>Tab</kbd><span>Indent the caret or every selected line by four spaces.</span></div>\n                  <div><kbd>Shift</kbd><span class=\"shortcut-plus\">+</span><kbd>Tab</kbd><span>Remove up to four leading spaces from the caret position or every selected line.</span></div>\n                  <div><kbd>Space</kbd><span>When text is selected, indent every selected line by exactly one space.</span></div>\n                </div>\n              </section>\n              <section id=\"shortcut-search\" class=\"information-section\">\n                <span class=\"information-kicker\">Search & selection</span>\n                <h3>Keyboard navigation</h3>\n                <div class=\"shortcut-grid\">\n                  <div><kbd>Enter</kbd><span>Run “Find node in graph” and jump to the next match.</span></div>\n                  <div><kbd>Esc</kbd><span>Close the compact graph-search overlay or an open searchable selector.</span></div>\n                  <div><kbd>↑</kbd><kbd>↓</kbd><span>Move through searchable selector options.</span></div>\n                  <div><kbd>Home</kbd><kbd>End</kbd><span>Jump to the first or last option in an open selector.</span></div>\n                  <div><kbd>Enter</kbd><kbd>Space</kbd><span>Choose the focused selector option.</span></div>\n                </div>\n              </section>\n              <section id=\"shortcut-color\" class=\"information-section\">\n                <span class=\"information-kicker\">Full Color Picker</span>\n                <h3>Precise saturation/value adjustment</h3>\n                <div class=\"shortcut-grid\">\n                  <div><kbd>←</kbd><kbd>→</kbd><span>Decrease / increase saturation by 0.01.</span></div>\n                  <div><kbd>↓</kbd><kbd>↑</kbd><span>Decrease / increase value by 0.01.</span></div>\n                  <div><kbd>Shift</kbd><span class=\"shortcut-plus\">+</span><kbd>Arrow</kbd><span>Use a larger 0.05 step.</span></div>\n                </div>\n              </section>\n            </article>\n          </div>\n        </section>\n\n        <section class=\"information-page information-node-page\" data-information-page=\"nodes\" hidden>\n          <div class=\"information-node-page-layout\">\n            <aside class=\"information-node-page-intro\">\n              <span class=\"information-kicker\">Builder node libraries</span>\n              <h3>Node reference</h3>\n              <nav class=\"information-node-scope-tabs\" aria-label=\"Node reference category\">\n                <button\n                  class=\"information-node-scope-tab active\"\n                  type=\"button\"\n                  data-information-node-scope-target=\"outline\"\n                  aria-controls=\"information-outline-node-panel\"\n                  aria-selected=\"true\"\n                  data-help=\"Show every control and structure node available in Configuration Outline.\">\n                  <span aria-hidden=\"true\">▤</span>\n                  <span>Configuration Outline</span>\n                </button>\n                <button\n                  class=\"information-node-scope-tab\"\n                  type=\"button\"\n                  data-information-node-scope-target=\"runtime\"\n                  aria-controls=\"information-runtime-node-panel\"\n                  aria-selected=\"false\"\n                  data-help=\"Show the existing complete Typed Runtime Graph node reference.\">\n                  <span aria-hidden=\"true\">◇</span>\n                  <span>Runtime Graph</span>\n                </button>\n              </nav>\n\n              <div data-information-node-scope-copy=\"outline\">\n                <p>\n                  Configuration Outline nodes define the generated RML settings menu:\n                  stored controls, impulse buttons, runtime display rows and structural\n                  containers. Their order and nesting are the menu layout.\n                </p>\n                <p class=\"information-api-note outline\">\n                  Click a palette node to add it to the active container, or drag it to\n                  an exact position. Every palette tooltip now describes the resulting\n                  menu control instead of repeating the visible badge and plus symbol.\n                </p>\n              </div>\n\n              <div data-information-node-scope-copy=\"runtime\" hidden>\n                <p>\n                  This is the complete reference for the builder's fixed built-in Runtime\n                  Graph nodes, including palette-hidden helper nodes. Advanced / Raw C#\n                  nodes remain deliberately separated from normal typed nodes.\n                </p>\n                <p>\n                  Custom C# appears once as a hybrid node whose Mode selects File, Action,\n                  Expression, Runtime Graph Member or Main Mod Member. C# Project and C#\n                  Reference remain advanced nodes. All three are usable in the Runtime Graph\n                  and inside an API &amp; Logic Graph; Roslyn syntax/token/trivia nodes are marked\n                  Custom C# File Graph only.\n                </p>\n                <p class=\"information-api-note\">\n                  Catalog-generated Resonite API nodes are version-derived rather than fixed\n                  builder nodes. Their collapsed categories and complete counts are always\n                  visible in the Node Library; opening one loads safe batches, while Node\n                  Search remains the fastest direct lookup for a generated Type, Enum,\n                  Constructor, Method, Property, Field or Event node.\n                </p>\n              </div>\n            </aside>\n\n            <article\n              id=\"information-outline-node-panel\"\n              class=\"information-node-page-content\"\n              data-information-node-scope-panel=\"outline\">\n              <div\n                id=\"information-outline-node-reference\"\n                class=\"information-node-reference information-outline-node-reference\"\n                aria-live=\"polite\"></div>\n            </article>\n\n            <article\n              id=\"information-runtime-node-panel\"\n              class=\"information-node-page-content\"\n              data-information-node-scope-panel=\"runtime\"\n              hidden>\n              <div id=\"information-node-reference\" class=\"information-node-reference\" aria-live=\"polite\"></div>\n            \n\n              <section id=\"info-outline-buttons\" class=\"information-section\">\n                <span class=\"information-kicker\">Start / Configuration</span>\n                <h3>Outline Button impulse outputs</h3>\n                <p>\n                  Every <strong>Button (Impulse)</strong> placed in Configuration\n                  Outline becomes one stable direct Impulse output on the packed Start\n                  node. Connect it to Branch, Sequence, method calls, stores, runtime\n                  menu actions or any other impulse input. The generated RML button\n                  invokes that exact output once per press. Visibility and absolute\n                  order remain controllable through the Configuration Menu nodes.\n                </p>\n              </section>\n\n              <section id=\"info-inline-layout\" class=\"information-section\">\n                <span class=\"information-kicker\">Configuration Menu</span>\n                <h3>Inline row layout, width and labels</h3>\n                <p>\n                  Every <strong>Inline row</strong> is exposed as a stable Menu Item on\n                  <strong>Configuration Menu Instance</strong>. Connect that output to\n                  <strong>Set Configuration Visibility</strong> to override the row's\n                  static Internal / hidden state, or to\n                  <strong>Set Configuration Layout</strong> and drive Horizontal with a\n                  Boolean to switch the open RML menu between side-by-side and stacked\n                  layout at runtime. Connect a direct child item to\n                  <strong>Set Configuration Width</strong> to override its percentage,\n                  or to <strong>Set Configuration Label Visibility</strong> to show or\n                  hide only its left-side label. The same outputs also work with Set\n                  Visibility, Set Order and Reset Configuration Item. Rebuilding preserves unsaved\n                  editor drafts. The connected action path is also simulated in Preview,\n                  so these changes are visible immediately there while remaining completely\n                  local; no Preview layout action is sent to Resonite.\n                </p>\n                <p>\n                  <strong>Save Configuration Settings</strong> is an Impulse action for\n                  Outline buttons. It first captures the values currently typed into the\n                  open RML menu, validates and persists them, then emits\n                  <strong>Done</strong>. Connect subsequent actions to Done so a button\n                  can save its sibling text field before rebuilding or changing the menu.\n                  <strong>Failed</strong> handles a missing menu, invalid input or a save\n                  error. Preview performs the same sequence against its browser-local draft\n                  only and never synchronizes it to Resonite.\n                </p>\n              </section>\n\n              <section id=\"info-dynamic-settings\" class=\"information-section\">\n                <span class=\"information-kicker\">Dynamic settings</span>\n                <h3>Collection-backed Dynamic Choice</h3>\n                <p>\n                  A Collect To List node marked <strong>Editable</strong> contributes one\n                  generated Dynamic Choice entry to the Configuration Outline palette.\n                  The entry is only a creation option until you explicitly click or drag it.\n                </p>\n                <p>\n                  Once placed in the Outline, the control uses the marked runtime collection\n                  as its only option source and is emitted as a normal typed Start / Configuration\n                  output after packing. No Labels/Stable Values monitor selection is needed.\n                  A Default selection can only be picked while the matching generated mod is\n                  running and the runtime list is available. The direct runtime subscription\n                  refreshes Properties and Preview immediately when that list changes; otherwise\n                  the first runtime item is used automatically unless empty selection is explicitly\n                  allowed. The Start-node value follows that effective runtime selection immediately\n                  when the collection changes. The control keeps its exact global Outline position among normal settings\n                  and Runtime Display rows. No setting is auto-inserted merely by enabling Mark as\n                  Editable.\n                </p>\n              </section>\n            </article>\n          </div>\n        </section>\n      </div>\n    </dialog>\n",
    writable: false,
    enumerable: false,
    configurable: true
  });
})();
